// Provided: a fast 32-bit string hash (FNV-1a + a final mix). Returns 0 .. 2^32-1.
function hash32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b);
  h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35);
  h ^= h >>> 16;
  return h >>> 0;
}

class HashRing {
  constructor({ vnodes = 100, hash = hash32 } = {}) {
    this.vnodes = vnodes;
    this.hash = hash;
    this.nodes = [];
  }
  addNode(name) { this.nodes.push(name); }
  removeNode(name) { this.nodes = this.nodes.filter((n) => n !== name); }
  getNode(key) {
    // Modulo hashing: simple, but adding/removing a node remaps almost everything.
    if (this.nodes.length === 0) return undefined;
    return this.nodes[this.hash(key) % this.nodes.length];
  }
}

