// Provided: a fast 32-bit string hash (FNV-1a + a final mix). Returns 0 .. 2^32-1.
function hash32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  h ^= h >>> 16; h = Math.imul(h, 0x85ebca6b);
  h ^= h >>> 13; h = Math.imul(h, 0xc2b2ae35);
  h ^= h >>> 16;
  return h >>> 0;
}

class HashRing {
  constructor({ vnodes = 100, hash = hash32 } = {}) {
    this.vnodes = vnodes;
    this.hash = hash;
    this.ring = []; // sorted [{ pos, node }]
  }

  addNode(name) {
    for (let i = 0; i < this.vnodes; i++) {
      this.ring.push({ pos: this.hash(name + '#' + i), node: name });
    }
    this.ring.sort((a, b) => a.pos - b.pos);
  }

  removeNode(name) {
    this.ring = this.ring.filter((p) => p.node !== name);
  }

  getNode(key) {
    if (this.ring.length === 0) return undefined;
    const h = this.hash(key);
    // binary search: first point with pos >= h
    let lo = 0, hi = this.ring.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.ring[mid].pos < h) lo = mid + 1; else hi = mid;
    }
    return this.ring[lo === this.ring.length ? 0 : lo].node; // wrap around
  }
}

