const r = new HashRing();
assertEqual(r.getNode('student:1'), undefined);
r.addNode('cache-a');
for (let i = 0; i < 50; i++) assertEqual(r.getNode('student:' + i), 'cache-a');

const pos = { 'A#0': 100, 'B#0': 200, 'C#0': 300, k1: 150, k2: 250, k3: 350, k4: 50, k5: 200 };
const r = new HashRing({ vnodes: 1, hash: (s) => pos[s] });
r.addNode('A'); r.addNode('B'); r.addNode('C');
assertEqual(['k1','k2','k3','k4','k5'].map(k => r.getNode(k)), ['B', 'C', 'A', 'A', 'B']);

const r = new HashRing();
['cache-a','cache-b','cache-c'].forEach(n => r.addNode(n));
const keys = Array.from({ length: 2000 }, (_, i) => 'student:' + i);
const before = keys.map(k => r.getNode(k));
r.removeNode('cache-b');
let moved = 0;
keys.forEach((k, i) => {
  const now = r.getNode(k);
  if (before[i] !== 'cache-b') assertEqual(now, before[i], k + ' should not move');
  else moved++;
  assert(now !== 'cache-b');
});
assert(moved > 0, 'cache-b should have owned some keys');

const r = new HashRing();
['cache-a','cache-b','cache-c'].forEach(n => r.addNode(n));
const keys = Array.from({ length: 4000 }, (_, i) => 'student:' + i);
const before = keys.map(k => r.getNode(k));
r.addNode('cache-d');
let moved = 0;
keys.forEach((k, i) => { const now = r.getNode(k); if (now !== before[i]) { moved++; assertEqual(now, 'cache-d', 'moved keys go to the new node'); } });
const frac = moved / keys.length;
assert(frac > 0.15 && frac < 0.35, 'expected ~25% of keys to move, got ' + (frac * 100).toFixed(1) + '%');

const r = new HashRing({ vnodes: 100 });
const nodes = ['cache-a','cache-b','cache-c','cache-d'];
nodes.forEach(n => r.addNode(n));
const count = {}; nodes.forEach(n => count[n] = 0);
for (let i = 0; i < 20000; i++) count[r.getNode('book:' + i)]++;
nodes.forEach(n => { const f = count[n] / 20000; assert(f > 0.17 && f < 0.33, n + ' got ' + (f * 100).toFixed(1) + '%'); });

